xfs_buf_t*
xfs_buf_find(struct xfs_buftarg	*btp,
		struct xfs_buf_map	*map,
		int			nmaps,
		xfs_buf_flags_t		flags,
		xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		blkno;
	size_t			numblks;
	int			error;

	blkno = XFS_BUF_FSB_TO_DADDR(btp, map[0].bm_bn);
	numblks = XFS_BUF_FSB_TO_BB(btp, map[0].bm_len);

	if (nmaps > 1) {
		uint	i;

		for (i = 1; i < nmaps; i++) {
			if (map[i].bm_bn != map[i-1].bm_bn + map[i-1].bm_len)
				return NULL;
			numblks += map[i].bm_len;
		}
	}

	bp = xfs_buf_find_agablock(btp, blkno, numblks);
	if (bp) {
		if (flags & XBF_TRYLOCK) {
			if (!xfs_buf_trylock(bp)) {
				xfs_buf_rele(bp);
				return NULL;
			}
		} else {
			xfs_buf_lock(bp);
		}

		if (XFS_BUF_ISSTALE(bp)) {
			xfs_buf_stale(bp);
			xfs_buf_unlock(bp);
			xfs_buf_rele(bp);
			return NULL;
		}
	} else {
		if (new_bp) {
			bp = new_bp;
			xfs_buf_init(bp, btp, numblks);
			bp->b_bn = blkno;
			xfs_buf_hold(bp);
			xfs_buf_insert(bp);
		}
	}

	return bp;
}

xfs_buf_t *
xfs_buf_find(struct xfs_buftarg *btp, struct xfs_buf_map *map, int nmaps,
		xfs_buf_flags_t flags, xfs_buf_t *new_bp)
{
	xfs_buf_t		*bp;
	struct xfs_buf		**bpp;
	struct xfs_buf_map	*tmp;
	xfs_daddr_t		first_block;
	int			i;
	int			nblocks = 0;

	for (i = 0; i < nmaps; i++) {
		nblocks += XFS_BUF_MAP_SIZE(&map[i]);
	}

	first_block = map[0].bm_bn;

	bp = xfs_buf_find_rbtree(btp, first_block, nblocks, flags, &bpp);
	if (bp) {
		if (XFS_BUF_ISSTALE(bp)) {
			xfs_buf_stale_unlock(bp);
			goto out;
		}
		xfs_buf_hold(bp);
		if (flags & XBF_LOCK) {
			xfs_buf_lock(bp);
		}
		goto out;
	}

	bp = new_bp;
	if (!bp)
		goto out;

	bp->b_bn = first_block;
	bp->b_bno = first_block;
	bp->b_bcount = nblocks;
	bp->b_target = btp;
	bp->b_flags = flags;
	xfs_buf_hold(bp);
	xfs_buf_lock(bp);

	xfs_buf_insert(bp, btp);

out:
	return bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		first_block;
	int			nblocks;
	int			i;
	struct xfs_mount	*mp = btp->bt_mount;

	nblocks = 0;
	first_block = NULLFSBLOCK;

	/*
	 * Check for alignment and calculate total size
	 */
	for (i = 0; i < nmaps; i++) {
		nblocks += XFS_MAP_BLOCK_COUNT(map[i].bm_len);
		if (i == 0)
			first_block = map[i].bm_bn;
	}

	/*
	 * Traverse the red-black tree to find a matching buffer
	 */
	bp = xfs_buf_find_which(btp, first_block, nblocks, flags);

	if (bp) {
		/*
		 * Handle stale buffers and lock
		 */
		if (xfs_buf_stale(bp)) {
			xfs_buf_stale_unlock(bp);
			xfs_buf_rele(bp);
			return NULL;
		}

		xfs_buf_lock(bp);
		return bp;
	}

	/*
	 * No match found; insert the new buffer
	 */
	if (new_bp) {
		new_bp->b_bn = first_block;
		new_bp->b_bno = first_block;
		new_bp->b_bcount = nblocks;
		new_bp->b_file = NULL;
		new_bp->b_flags |= flags;

		xfs_buf_insert(new_bp, btp);
		xfs_buf_lock(new_bp);

		return new_bp;
	}

	return NULL;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	struct xfs_buf		*newbuf = NULL;
	xfs_daddr_t		daddr;
	int			nbytes = 0;
	int			i;

	if (nmaps <= 0)
		return NULL;

	/*
	 * Calculate the total number of bytes for all mappings.
	 */
	for (i = 0; i < nmaps; i++) {
		nbytes += map[i].bm_len;
		if (XFS_BUF_ADDR(map) == NULL) {
			/* Invalid address */
			return NULL;
		}
	}

	/* Validate alignment and check for corruption */
	if ((nbytes & (btp->bt_bsize - 1)) != 0) {
		/* Not aligned to block size */
		return NULL;
	}

	/*
	 * Traverse the red-black tree of buffers to find a matching block.
	 * For simplicity, assume we check the first mapping's block address.
	 */
	daddr = map[0].bm_bn << (btp->bt_sshift);

	bp = xfs_buf_find_which(btp, daddr, flags);
	if (bp) {
		/* Found a buffer */
		if ((bp->b_flags & XBF_STALE) && !(flags & XBF_TRYLOCK)) {
			/* Handle stale buffer */
			xfs_buf_rele(bp);
			return NULL;
		}

		/* Lock the buffer if necessary */
		if (flags & XBF_TRYLOCK) {
			if (!xfs_buf_lock_nowait(bp)) {
				xfs_buf_rele(bp);
				return NULL;
			}
		} else {
			xfs_buf_lock(bp);
		}

		return bp;
	}

	/*
	 * If no match is found, insert a new buffer.
	 */
	if (new_bp) {
		newbuf = new_bp;
	} else {
		/* Allocate a new buffer */
		newbuf = xfs_buf_alloc(btp, daddr, nbytes, flags);
		if (!newbuf)
			return NULL;
	}

	/* Insert the new buffer into the tree */
	xfs_buf_insert(newbuf);

	/* Return the new buffer */
	return newbuf;
}

xfs_buf_t*
xfs_btree_lookup_buffer(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		daddr;
	int			i;
	int			numblks = 0;
	int			error = 0;

	for (i = 0; i < nmaps; i++) {
		numblks += XFS_BUF_MAP_BLKSIZE(map[i].bm_bn, map[i].bm_len);
	}

	if (!numblks)
		return NULL;

	daddr = map[0].bm_bn;

	bp = xfs_buf_find(btp, daddr, numblks, flags, &error);
	if (bp) {
		if (xfs_buf_is_busy(bp)) {
			xfs_buf_rele(bp);
			return NULL;
		}

		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
			xfs_buf_rele(bp);
			return NULL;
		}

		xfs_buf_lock(bp);
		return bp;
	}

	if (new_bp) {
		new_bp->b_bn = daddr;
		new_bp->b_bcount = numblks;
		new_bp->b_flags = flags;
		xfs_buf_insert(new_bp, btp);
		return new_bp;
	}

	return NULL;
}
